const b=$json.body??$json;
const required=['organization_id','agent_id','idempotency_key','channel','event_type','input'];
const missing=required.filter(k=>b[k]===undefined||b[k]===null||b[k]==='');
if(missing.length) throw new Error('Missing required tenant fields: '+missing.join(', '));

const allowedChannels=['whatsapp','email','web_chat','telegram','voice','internal'];
if(!allowedChannels.includes(b.channel)) throw new Error('Unsupported channel');

const allowedEvents=[
  'appointment.requested',
  'appointment.confirmed',
  'appointment.reschedule_requested',
  'appointment.cancel_requested',
  'appointment.reminder_due',
  'appointment.no_show',
  'appointment.completed'
];
if(!allowedEvents.includes(b.event_type)) throw new Error('Unsupported appointment event');

const input=b.input||{};
const customerKey=String(b.customer_id||input.customer_key||input.email||input.phone||'').trim();
if(!customerKey) throw new Error('customer_id or customer identifier required');

return [{json:{
  organization_id:String(b.organization_id),
  agent_id:String(b.agent_id),
  conversation_id:b.conversation_id||null,
  customer_id:b.customer_id||null,
  customer_key:customerKey,
  appointment_id:b.appointment_id||input.appointment_id||null,
  idempotency_key:String(b.idempotency_key),
  channel:b.channel,
  event_type:b.event_type,
  external_thread_key:b.external_thread_key||input.external_thread_key||null,
  input,
  received_at:new Date().toISOString(),
  workflow_key:'appointment_booking_v4'
}}];

const ctx=$('Build Appointment Request').first().json;
let raw=$json.output_text||$json.text||$json.response_text;
if(!raw&&Array.isArray($json.output)) raw=$json.output.flatMap(x=>x.content||[]).map(x=>x.text||x.output_text||'').join('');
raw=String(raw||'').replace(/^```json\s*/i,'').replace(/```$/,'').trim();

let d;
try{d=JSON.parse(raw)}catch(e){throw new Error('Invalid appointment AI JSON: '+raw.slice(0,300))}

const actions=['book','reschedule','cancel','confirm','remind','complete','mark_no_show','request_information','handoff','skip'];
const statuses=['requested','pending_availability','confirmed','rescheduled','cancelled','completed','no_show','needs_information'];
const locationTypes=['virtual','physical','phone','unspecified'];

d.action=actions.includes(d.action)?d.action:'request_information';
d.status=statuses.includes(d.status)?d.status:'needs_information';
d.location_type=locationTypes.includes(d.location_type)?d.location_type:'unspecified';
d.confidence=Math.max(0,Math.min(1,Number(d.confidence)||0));
d.duration_minutes=d.duration_minutes==null?null:Math.max(5,Math.min(1440,Math.round(Number(d.duration_minutes)||30)));
d.reminder_offsets_minutes=Array.isArray(d.reminder_offsets_minutes)?[...new Set(d.reminder_offsets_minutes.map(Number).filter(n=>Number.isFinite(n)&&n>0&&n<=10080).map(Math.round))].sort((a,b)=>b-a):[];
d.missing_information=Array.isArray(d.missing_information)?d.missing_information:[];
d.memory_facts=Array.isArray(d.memory_facts)?d.memory_facts:[];
d.calendar_action_required=Boolean(d.calendar_action_required&&['book','reschedule','cancel','confirm'].includes(d.action));
d.notification_required=Boolean(d.notification_required||['book','reschedule','cancel','confirm','remind'].includes(d.action));
d.handoff_required=Boolean(d.handoff_required||d.action==='handoff');

return [{json:{...ctx,decision:d,provider_usage:$json.usage||{},provider_response_id:$json.id||null}}];

const r=$json;
const actions=[];
if(r.calendar_action) actions.push({type:'appointment',payload:r.calendar_action});
if(r.notification_action) actions.push({type:'reply',payload:r.notification_action});
if(r.handoff) actions.push({type:'handoff',payload:r.handoff});
for(const reminder of (r.reminder_actions||[])) actions.push({type:'follow_up',payload:reminder});
return [{json:{...r,actions}}];
